INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('866405b4-3032-49b9-8723-5a4ae5b4ba5b', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "679b328a-fa43-4f9e-bf12-7d2b4ac88b8e", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d774e05f-5b0d-4b06-8fec-fb49cd563095", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "6b5f7b40-fd3f-40f6-92df-35aa7005ef65", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "3bac1373-ef82-4105-87de-e8f074a00da4", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "070aab71-c333-4e12-afd9-70d658380006", "text": "Igaz", "isCorrect": true}, {"id": "6deda400-c30f-4d3f-86a6-cfe07d94d627", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ae0a1cfb-f163-4750-b5cb-45def15e57bd", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "31ac8048-ea8e-4add-8430-8c010c10d94c", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "7db5e482-b2af-4d45-b87a-bf1b542bd68d", "text": "-4", "isCorrect": true}, {"id": "e9727e60-e619-4039-ad5a-76211f408946", "text": "-12", "isCorrect": false}, {"id": "6084e510-40f6-4509-9f6c-bd5fc2f00165", "text": "Egyenlők", "isCorrect": false}, {"id": "a052eca6-096b-4da2-81c6-3ce5e61b283e", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "080a7590-f11e-46a9-9d1e-2a18d17728b5", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9918b5ca-ec1b-4d73-8aef-d6aa87fc5f56', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "55a6ccbb-9068-4eb4-9836-f4380a1ef5e0", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "94eba5ba-dbb1-49e8-b453-966616a9a080", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "91256a17-3310-48de-8254-f9fada5273f0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e1309f93-d8f4-4718-96a7-d0218f34b96f", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "a53ec1ff-be20-49ed-9c76-9fde35401e13", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "5d4fb071-3280-4744-b3e3-293822261058", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a2554127-88dc-4712-9493-90df24c47b02", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "ac1b665a-55f8-48ea-85ef-2902d3fed774", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "97963c25-0a2b-448e-bdfe-2a5a02e664f3", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "6e89857a-f0d0-44a8-913b-15647cde7f92", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "7189da9f-e028-4179-bae9-d53e6c83af68", "text": "Igaz", "isCorrect": true}, {"id": "d0b645bc-09f9-4c40-84cd-6c046c4f0ca1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4db405cf-b709-4574-93f1-653b59ea95ac", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "c1b99d3f-9ef4-4164-96c1-52940deeaf5c", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "4614f552-6848-4c78-a351-f8f8b4b2fa05", "text": "815", "isCorrect": false}, {"id": "8551f685-6f65-47ac-a064-a520fbc2f07d", "text": "812", "isCorrect": false}, {"id": "7d21d89a-d079-4a19-9ac6-41b738253cdd", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('835c873c-7439-4ba2-a402-e4b4bdb91737', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "a05314eb-2323-4e9f-ab91-2533755f64d9", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "6525d8f2-7308-42c4-a012-c55aa61741e0", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "216cbfae-64a8-4753-8450-3abf472d504c", "text": "4/6", "isCorrect": false}, {"id": "bf5bba1f-cd6d-4b77-8435-2acdd39d8573", "text": "4/4", "isCorrect": false}, {"id": "e660cfa5-b5f8-4399-a24b-d3ce1316a7ba", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "e52a2357-f97c-48b8-8b0d-6efffdd46649", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "7a2bc016-dd4a-49ec-9235-cf7cbb2a1e03", "text": "2/5", "isCorrect": true}, {"id": "fbd9b11c-981e-4057-a6ae-3317c9dbab24", "text": "6/15", "isCorrect": false}, {"id": "e552e684-3355-4bf8-a10f-4a744a686dd4", "text": "5/8", "isCorrect": false}, {"id": "d05bdf2d-b4d3-48b5-a363-e2ecc1e1153f", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "d6db7beb-8c9f-444f-8306-cf7a14ca4e1f", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "24a6da26-db71-4daf-b6ae-14184e074d3d", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "f742a736-94ca-4267-a2a7-3351bbbad276", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "bea445c6-7636-45e5-a33b-f05b3c0c8031", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "64fba506-7757-4ffa-8e82-d0b153bcb90c", "text": "Igaz", "isCorrect": true}, {"id": "39d2176e-8a4e-4811-9cae-4a5d847679b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "396eabb5-45ee-492f-b829-dd8de47721a8", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9a5bffbb-a6fd-4aff-80de-5eb1cdfe41e8', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "dbbb7a11-3b19-4f61-be9a-b65f0e661a8e", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "9df804ce-5e20-4eec-ba3a-4b428a4b2de9", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "ffae0fd0-f91b-4415-8fbf-917467d0e6f7", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "04ff1883-2c86-4393-ae04-1c49823723a8", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1f5140a5-c905-463a-b169-bbbced781c8a", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "0c3eebf2-bb62-4af7-9e65-0844b6a6ed42", "text": "Igaz", "isCorrect": true}, {"id": "768a26fa-6dc8-4e0e-a96d-c44a4e221742", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "122257c8-a4a4-4431-8019-c8b501df5059", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a25ffc75-5997-44e3-90c4-eed17893df4b", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "ec07be2b-77fd-4c35-9518-7ee2f49eb232", "text": "Derékszög", "isCorrect": true}, {"id": "a5035b2e-bac0-4238-845d-1bdeeef8e4b3", "text": "Hegyesszög", "isCorrect": false}, {"id": "3f6d2201-a6ce-4371-b71b-62e9c776911e", "text": "Tompaszög", "isCorrect": false}, {"id": "62a9594f-71f8-4242-8edb-75e707421cc0", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('38ea238c-2411-479f-8082-bc544411c536', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "b79079a9-f49a-4a7d-8565-b7e6522401c0", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "6a87c859-93b5-4e28-8aed-b585a1b8cbb8", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "7a384322-4b7a-4b20-bf06-23ae33890bb4", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "dfdb1b9d-fb40-4d32-9647-1cfb0b85515f", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "66831a4b-8c60-4fae-9504-d18f1472ec72", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "3974526b-981f-415d-8cfa-7744d49ff9c6", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "18bb2630-de6e-47ce-96ef-901a29a4549b", "text": "Igaz", "isCorrect": true}, {"id": "d4758338-5a76-45a3-adbb-191232b5839e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "14b06ec3-8f4d-4c83-95e8-8071a648701a", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3eea6724-492a-4ca7-aaa7-956e39593434', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "8111f17f-d30c-46ea-9de3-212c3d167bab", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "bbe2d7eb-5ca8-420d-b844-4be0c7b3f9f7", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "75657c95-60b3-47f1-b6bf-d4c22eed1b4e", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "24f4687c-1319-4d6d-8d41-7a900f635036", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "8e43594b-35b4-45e9-ace0-142b1fbc561d", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "dac5252c-f501-46a6-9d39-24a515d55bc6", "text": "Igaz", "isCorrect": true}, {"id": "b73859e3-7f05-4ae9-ba82-e01b31aa91fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fe7a607e-9c1f-4dae-8cb3-af4933a30f2f", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "c4d120d8-4baa-457e-8f56-4fbaa30bcb44", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f32bcaa8-4fc7-4669-8213-eafe674d81f4', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "37748926-c4f2-450d-bed8-952d4b92f810", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "25e1edb2-55ef-4865-8431-08eddbda6fc5", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "ca21245e-fe27-46a4-a251-6de6b39f4073", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "cf76d30e-826e-4f51-9016-1a778490f90e", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "0addd337-b595-4621-9877-13f43184f375", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "4ec3d1d5-95a2-4c8c-a5f7-b21a3bb74aca", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "dbb3d773-4cf4-43e1-ac37-19c86220fbf4", "text": "Igaz", "isCorrect": true}, {"id": "78fb6b25-3c00-4b01-91c1-89a5ae4fc87e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "68b29060-bbb6-44f4-ad5a-030a1c143d51", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "5e6503b9-f61e-451a-929a-b4e24e937914", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "2577226f-77f4-49b6-844e-c95b0dd372ce", "text": "Igaz", "isCorrect": true}, {"id": "da7a3677-0bd2-44db-bc8f-f963174a87f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f8826a6c-ea9a-44a9-ba1c-dc152424beb5", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "cdb59acb-cfe0-4af8-9adc-67ab7bc80ad2", "text": "Igaz", "isCorrect": true}, {"id": "a200e394-94e5-408f-9907-e86ac1d4e5f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a6d1a629-557d-4a36-8778-c0a4f1bb4446", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "09824de2-6c64-44e0-9013-6257c07a9ec5", "text": "Igaz", "isCorrect": true}, {"id": "f2738bac-9528-4663-bf37-a89077febf8d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6a7d1f9-3b3a-4be4-94f4-260a4849cc2d", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "6b8cdad2-fc68-4b81-a06e-da4fd7af64c9", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "dcf39a2d-6067-4f38-8879-d385ce87a9c3", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "ee7ced3c-c16e-4427-afd2-342e042b0da9", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "d69add89-b1bc-4e14-8e77-0365508bd573", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());